def sieve_bytearray(n: int) -> int:
    """Sieve of Eratosthenes on a flat bytearray; returns pi(n)."""
    flags = bytearray([1]) * (n + 1)
    flags[0:2] = b"\x00\x00"
    for i in range(2, int(n**0.5) + 1):
        if flags[i]:
            start = i * i
            flags[start::i] = bytearray(len(range(start, n + 1, i)))
    return sum(flags)


def sieve_set(n: int) -> int:
    """Set-based sieve: keep candidates in a set, subtract multiples; pi(n)."""
    nums = set(range(2, n + 1))
    for i in range(2, int(n**0.5) + 1):
        if i in nums:
            nums -= set(range(i * i, n + 1, i))
    return len(nums)
